package emon;


public final class Initialtest {
    public static int itPut(emon.Port.Cells c, byte[] b) {
        // The ASCII text of b as code points appended to c; answers where they start.
        int start = emon.Port.blobLen(b);
        int i = 0;
        while (i < start) {
            emon.Port.cellsPush(c, emon.Port.blobU8(b, i));
            i += 1;
        }
        return 0;
    }
    public static int itJoin(emon.Port.Cells loc, int cp, byte[] word) {
        // `in-join` for an initial of the one code point cp before `word`.
        emon.Port.Cells et = emon.Port.newCells();
        itPut(et, word);
        return Initial.inJoin(loc, cp, et, 0, emon.Port.blobLen(word));
    }
    public static int itLang(byte[] tag) {
        emon.Port.Cells loc = emon.Port.newCells();
        itPut(loc, tag);
        return Initial.inLang(loc);
    }
    public static void testALocaleTagNamesALanguage() {
        emon.Testport.assertEq(itLang(emon.Testport.textBlob("")), 0, "no tag");
        emon.Testport.assertEq(itLang(emon.Testport.textBlob("e")), 0, "one letter is no tag");
        emon.Testport.assertEq(itLang(emon.Testport.textBlob("en")), 1, "en");
        emon.Testport.assertEq(itLang(emon.Testport.textBlob("EN-us")), 1, "case does not matter, a region follows");
        emon.Testport.assertEq(itLang(emon.Testport.textBlob("en_GB")), 1, "an underscore too");
        emon.Testport.assertEq(itLang(emon.Testport.textBlob("de-CH")), 2, "de");
        emon.Testport.assertEq(itLang(emon.Testport.textBlob("fr")), 3, "fr");
        emon.Testport.assertEq(itLang(emon.Testport.textBlob("es-419")), 4, "es");
        emon.Testport.assertEq(itLang(emon.Testport.textBlob("pt-BR")), 5, "pt");
        emon.Testport.assertEq(itLang(emon.Testport.textBlob("it")), 6, "it");
        emon.Testport.assertEq(itLang(emon.Testport.textBlob("nl-BE")), 7, "nl");
        emon.Testport.assertEq(itLang(emon.Testport.textBlob("zh-Hans")), 99, "a language without a table");
        emon.Testport.assertEq(itLang(emon.Testport.textBlob("english")), 99, "a word is not a tag");
    }
    public static void testTheJoinWithoutALocale() {
        emon.Port.Cells none = emon.Port.newCells();
        emon.Testport.assertEq(itJoin(none, 65, emon.Testport.textBlob("long")), 1, "`A` + `long`: joined, flagged (the union of the tables has `A`)");
        emon.Testport.assertEq(itJoin(none, 73, emon.Testport.textBlob("t")), 1, "`I` + `t`: flagged too");
        emon.Testport.assertEq(itJoin(none, 69, emon.Testport.textBlob("verything")), 1, "`E` is a word in Spanish, Italian, Portuguese");
        emon.Testport.assertEq(itJoin(none, 84, emon.Testport.textBlob("he")), 0, "`T` + `he`: no language has a word `T`");
        emon.Testport.assertEq(itJoin(none, 81, emon.Testport.textBlob("uiet")), 0, "`Q` + `uiet`");
        emon.Testport.assertEq(itJoin(none, 65, emon.Testport.textBlob("")), 1, "no word after it: still flagged");
    }
    public static void testTheJoinWithALocale() {
        emon.Port.Cells en = emon.Port.newCells();
        emon.Port.Cells de = emon.Port.newCells();
        emon.Port.Cells fr = emon.Port.newCells();
        emon.Port.Cells zh = emon.Port.newCells();
        itPut(en, emon.Testport.textBlob("en-US"));
        itPut(de, emon.Testport.textBlob("de"));
        itPut(fr, emon.Testport.textBlob("fr"));
        itPut(zh, emon.Testport.textBlob("zh"));
        // English lists: the words a one-letter word is followed by, and the rest of a word the letter begins.
        emon.Testport.assertEq(itJoin(en, 65, emon.Testport.textBlob("long")), 2, "`A` + `long`: a space, the letter is a word");
        emon.Testport.assertEq(itJoin(en, 73, emon.Testport.textBlob("was")), 2, "`I` + `was`");
        emon.Testport.assertEq(itJoin(en, 73, emon.Testport.textBlob("t")), 0, "`I` + `t`: `It`, sure");
        emon.Testport.assertEq(itJoin(en, 65, emon.Testport.textBlob("t")), 0, "`A` + `t`: `At`");
        emon.Testport.assertEq(itJoin(en, 79, emon.Testport.textBlob("nce")), 0, "`O` + `nce`: `Once`");
        emon.Testport.assertEq(itJoin(en, 65, emon.Testport.textBlob("xyzzy")), 1, "a word neither list knows: joined, flagged");
        emon.Testport.assertEq(itJoin(en, 84, emon.Testport.textBlob("he")), 0, "`T` is no word");
        emon.Testport.assertEq(itJoin(en, 97, emon.Testport.textBlob("long")), 2, "a lower-case letter is read as its capital");
        // A language with a one-letter table and no list joins and flags; one without the letter joins.
        emon.Testport.assertEq(itJoin(de, 79, emon.Testport.textBlob("ma")), 1, "German `O`");
        emon.Testport.assertEq(itJoin(de, 65, emon.Testport.textBlob("long")), 0, "German has no one-letter `A`");
        emon.Testport.assertEq(itJoin(fr, 192, emon.Testport.textBlob("propos")), 1, "French `À`");
        emon.Testport.assertEq(itJoin(zh, 65, emon.Testport.textBlob("long")), 1, "a language without a table: the union");
    }
}
